import { useCallback, useMemo, useState } from "react";
import { useUniqueId } from "@system";

import { InputProps } from "../input.types";

export const useInputState = ({
  id,
  value: controlledValue,
  defaultValue,
  maxLength,
  onChange,
  restrictCharacterCount,
  ["aria-describedby"]: ariaDescribedBy,
  disabled,
}: InputProps) => {
  const [uncontrolledValue, setUncontrolledValue] = useState(
    defaultValue !== undefined ? String(defaultValue) : "",
  );
  const [describedBy, setDescribedBy] = useState<string[]>([]);
  const generatedId = useUniqueId("input");
  const inputId = id || generatedId;

  const isControlled = controlledValue !== undefined;
  const currentValue = isControlled ? controlledValue : uncontrolledValue;

  const handleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled) return;

      let newValue = event.target.value;
      if (restrictCharacterCount && maxLength && newValue.length > maxLength) {
        newValue = newValue.slice(0, maxLength);
      }

      if (!isControlled) {
        setUncontrolledValue(newValue);
      }

      onChange?.({
        ...event,
        stopPropagation: event.stopPropagation.bind(event),
        preventDefault: event.preventDefault.bind(event),
        target: { ...event.target, value: newValue },
      });
    },
    [restrictCharacterCount, maxLength, onChange, disabled, isControlled],
  );

  const clearValue = useCallback(() => {
    if (disabled) return;
    if (!isControlled) {
      setUncontrolledValue("");
    }
    onChange?.({ target: { value: "" } } as React.ChangeEvent<HTMLInputElement>);
  }, [disabled, isControlled, onChange]);

  const addAriaDescribedBy = useCallback((id: string) => {
    setDescribedBy((prev) => [...prev, id]);
  }, []);

  const removeAriaDescribedBy = useCallback((id: string) => {
    setDescribedBy((prev) => prev.filter((item) => item !== id));
  }, []);

  const getAriaDescribedBy = useMemo(() => {
    const describedByIds = [...describedBy, ...(ariaDescribedBy ? ariaDescribedBy.split(" ") : [])]
      .filter(Boolean)
      .join(" ");

    return describedByIds;
  }, [ariaDescribedBy, describedBy]);

  return {
    inputId,
    currentValue,
    describedBy,
    handleChange,
    clearValue,
    addAriaDescribedBy,
    removeAriaDescribedBy,
    getAriaDescribedBy,
  };
};
